using System;
using System.Collections.Generic;
using System.Drawing;
using System.IO;
using System.Linq;
using System.Reflection;
using System.Windows.Forms;
namespace Stackshot
{
    static class AnnotationExtrasTests
    {
        sealed class ShiftPen:Canvas{internal ShiftPen(Bitmap image):base(image){ModifierSource=delegate{return Keys.Shift;};}internal void Stroke(PointF a,PointF middle,PointF b){var x=ImageToControl(a);var y=ImageToControl(middle);var z=ImageToControl(b);OnMouseDown(new MouseEventArgs(MouseButtons.Left,1,x.X,x.Y,0));OnMouseMove(new MouseEventArgs(MouseButtons.Left,0,y.X,y.Y,0));OnMouseMove(new MouseEventArgs(MouseButtons.Left,0,z.X,z.Y,0));OnMouseUp(new MouseEventArgs(MouseButtons.Left,1,z.X,z.Y,0));}}
        static IEnumerable<Control> Children(Control parent){foreach(Control c in parent.Controls){yield return c;foreach(var d in Children(c))yield return d;}}
        static void Click(Button button){typeof(Button).GetMethod("OnClick",BindingFlags.Instance|BindingFlags.NonPublic).Invoke(button,new object[]{EventArgs.Empty});}
        static Bitmap Source(int width=1000,int height=700){var image=new Bitmap(width,height);using(var g=Graphics.FromImage(image)){g.Clear(Color.FromArgb(225,230,237));for(int x=0;x<width;x+=8)g.DrawLine(Pens.DarkSlateBlue,x,0,x,height);}return image;}
        static CaptureOverlay Overlay(Preferences p=null){return new CaptureOverlay(Source(),new Rectangle(0,0,1000,700),new Rectangle(100,90,750,430),new[]{new Rectangle(0,0,1000,680)},null,70,p);}
        static string Hash(Bitmap image){using(var stream=new MemoryStream()){image.Save(stream,System.Drawing.Imaging.ImageFormat.Png);using(var sha=System.Security.Cryptography.SHA256.Create())return Convert.ToBase64String(sha.ComputeHash(stream.ToArray()));}}
        static int Different(Bitmap a,Bitmap b,Rectangle r){int n=0;for(int y=r.Top;y<r.Bottom;y++)for(int x=r.Left;x<r.Right;x++)if(a.GetPixel(x,y).ToArgb()!=b.GetPixel(x,y).ToArgb())n++;return n;}
        public static void Run(Action<string,Action> run,Action<bool,string> check,string output)
        {
            run("guides/manual range adjustment repaints both crosshair lines erases old lines and excludes export",delegate{using(var o=Overlay()){var c=o.AnnotationCanvas;using(var before=UiPaintingTests.NativePaint(c,Color.Magenta)){o.BeginRangeDrag(3,new Point(850,300));using(var guide=UiPaintingTests.NativePaint(c,Color.Lime)){check(guide.GetPixel(20,300).B>before.GetPixel(20,300).B+80&&guide.GetPixel(850,20).B>before.GetPixel(850,20).B+80,"manual crosshair absent");guide.Save(Path.Combine(output,"manual-range-crosshair-native.png"));}o.UpdateRangeDrag(new Point(890,330));using(var moved=UiPaintingTests.NativePaint(c,Color.Magenta))check(moved.GetPixel(850,20).ToArgb()==before.GetPixel(850,20).ToArgb(),"old guide remained");o.EndRangeDrag();using(var ended=UiPaintingTests.NativePaint(c,Color.Magenta))check(ended.GetPixel(890,20).ToArgb()==before.GetPixel(890,20).ToArgb(),"guide not cleared");using(var export=c.Render())check(export.GetPixel(30,30).ToArgb()==c.Img.GetPixel(130,120).ToArgb(),"guide exported");}}});
            run("keyboard/range move fine coarse opposing edges clamp and independent pin movement",delegate{var r=new Rectangle(100,100,300,200);var area=new Rectangle(0,0,1000,700);check(CaptureKeyboard.AdjustRange(r,Keys.Right,area)==new Rectangle(101,100,300,200),"one pixel move");check(CaptureKeyboard.AdjustRange(r,Keys.Shift|Keys.Down,area).Y==110,"coarse move");check(CaptureKeyboard.AdjustRange(r,Keys.Control|Keys.Right,area).Width==301,"Ctrl resize right");check(CaptureKeyboard.AdjustRange(r,Keys.Alt|Keys.Right,area)==new Rectangle(101,100,299,200),"Alt resize left");check(CaptureKeyboard.AdjustRange(r,Keys.Control|Keys.Shift|Keys.Down,area).Height==210,"coarse resize");using(var a=PinWindow.CreateHidden(AnnotationDocument.FromImage(new Bitmap(200,120)),area))using(var b=PinWindow.CreateHidden(AnnotationDocument.FromImage(new Bitmap(200,120)),area)){var start=a.Location;var other=b.Bounds;a.ApplyPinKey(Keys.Right);a.ApplyPinKey(Keys.Shift|Keys.Down);check(a.Location==new Point(start.X+1,start.Y+10)&&b.Bounds==other&&!a.Visible&&!b.Visible,"pin keyboard isolation");}});
            run("pen/smoothing lowers jitter preserves endpoints and raw editable stroke",delegate{var raw=Enumerable.Range(0,30).Select(i=>new PointF(40+i*8,80+(i%2==0?7:-7))).ToArray();var smooth=Painter.SmoothPoints(raw);check(smooth[0]==raw[0]&&smooth.Last()==raw.Last()&&smooth.Skip(1).Take(28).Sum(p=>Math.Abs(p.Y-80))<raw.Skip(1).Take(28).Sum(p=>Math.Abs(p.Y-80))/2,"smoothing did not reduce jitter");using(var c=new Canvas(Source(400,260))){var pen=ScreenCraftTests.Mark(Tool.Pen,40,80,272,73);pen.Points=raw.ToList();c.AddAnnotation(pen);using(var a=c.Render()){c.EditSelected(delegate(Shape s){s.SmoothPen=true;});using(var b=c.Render())check(Hash(a)!=Hash(b),"smooth mode did not change output");}check(c.SelectedShape.Points.SequenceEqual(raw),"raw stroke overwritten");c.Undo();check(!c.AnnotationSnapshot.Single().SmoothPen,"smoothing undo");}});
            run("arrows/freehand arrow and filled white-outline preset produce distinct visible pixels",delegate{using(var image=new Bitmap(420,280)){using(var g=Graphics.FromImage(image))g.Clear(Color.FromArgb(30,36,46));using(var c=new Canvas(image)){var pen=ScreenCraftTests.Mark(Tool.Pen,45,40,210,170);pen.Color=Color.Yellow;pen.Width=6;pen.SmoothPen=true;pen.FreehandArrow=true;pen.Points=new List<PointF>{new PointF(45,40),new PointF(75,70),new PointF(55,110),new PointF(95,140),new PointF(210,170)};c.AddAnnotation(pen);var arrow=ScreenCraftTests.Mark(Tool.Arrow,110,230,365,175);arrow.Width=8;arrow.ArrowWhiteOutline=true;c.AddAnnotation(arrow);using(var painted=c.Render()){int white=0;for(int y=130;y<270;y++)for(int x=90;x<400;x++){var color=painted.GetPixel(x,y);if(color.R>240&&color.G>240&&color.B>240)white++;}check(white>100,"white arrow edge missing");painted.Save(Path.Combine(output,"smooth-freehand-outline-arrows-offscreen.png"));}c.EditSelected(delegate(Shape s){s.ArrowWhiteOutline=false;});using(var normal=c.Render()){c.EditSelected(delegate(Shape s){s.ArrowWhiteOutline=true;});using(var outlined=c.Render())check(Hash(normal)!=Hash(outlined),"outline preset ignored");}}}});
            run("memo/text image wraps respects colors padding and transparent corners",delegate{var style=new TextMemoStyle{MaxWidth=280,Padding=20,FontPx=20,BackgroundColor=Color.FromArgb(124,58,237),TextColor=Color.White};using(var shortMemo=TextMemoRenderer.Render("备忘 memo",style))using(var longMemo=TextMemoRenderer.Render(string.Join(" ",Enumerable.Repeat("建筑 analysis",24)),style)){check(longMemo.Width<=280&&longMemo.Height>shortMemo.Height&&shortMemo.GetPixel(0,0).A==0,"memo layout or corner alpha");check(longMemo.GetPixel(20,longMemo.Height-12).A==255,"background not rendered");longMemo.Save(Path.Combine(output,"text-memo-render-offscreen.png"));}bool rejected=false;try{using(var empty=TextMemoRenderer.Render(" ",style)){}}catch(ArgumentException){rejected=true;}check(rejected,"empty memo pinned");});
            run("memo/hidden dialog reads only through adapter previews style and hands ownership to pin",delegate{Bitmap pinned=null;using(var dialog=new TextMemoDialog("初稿")){int reads=0;dialog.ReadClipboardText=delegate{reads++;return "Memo fixture\n文字备忘与建筑分析";};dialog.PinOutput=delegate(Bitmap image){pinned=image;};var controls=Children(dialog).ToArray();check(reads==0,"read clipboard without command");Click(controls.OfType<Button>().Single(b=>b.Text=="读取剪贴板"));controls.OfType<NumericUpDown>().Single(n=>n.AccessibleName=="备忘最大宽度").Value=260;dialog.RefreshPreview();using(var preview=dialog.RenderOffscreen())preview.Save(Path.Combine(output,"text-memo-dialog-offscreen.png"));Click(controls.OfType<Button>().Single(b=>b.Text=="钉到桌面"));check(reads==1&&pinned!=null&&!dialog.Visible,"memo callback or visibility");}using(pinned)check(pinned.Width<=260&&pinned.Height>30,"pin image ownership lost");});
            run("effects/blur and colorful opaque redaction preserve pixels outside selection and switch modes",delegate{using(var c=new Canvas(Source(400,260))){var s=ScreenCraftTests.Mark(Tool.Pixelate,60,60,300,180);s.RedactionMode=1;s.MosaicBlock=24;c.AddAnnotation(s);using(var blur=c.Render()){check(blur.GetPixel(10,10).ToArgb()==c.Img.GetPixel(10,10).ToArgb()&&Different(blur,c.Img,new Rectangle(70,70,220,100))>1000,"blur changed exterior or not rendered");c.EditSelected(delegate(Shape mark){mark.RedactionMode=2;});using(var dots=c.Render()){check(Hash(blur)!=Hash(dots)&&dots.GetPixel(60,60).A==255,"dots mode missing or transparent");dots.Save(Path.Combine(output,"color-dot-redaction-offscreen.png"));}}c.EditSelected(delegate(Shape mark){mark.RedactionMode=0;});using(var pixel=c.Render())check(pixel.GetPixel(10,10).ToArgb()==c.Img.GetPixel(10,10).ToArgb(),"mode cache corrupted exterior");}});
            run("effects/spotlight keeps hole undimmed and opaque redaction removes original detail",delegate{using(var c=new Canvas(Source(400,260))){c.AddAnnotation(ScreenCraftTests.Mark(Tool.Spotlight,80,60,280,190));using(var light=c.Render()){check(light.GetPixel(140,100).ToArgb()==c.Img.GetPixel(140,100).ToArgb()&&light.GetPixel(20,20).R<c.Img.GetPixel(20,20).R,"spotlight hole or dimming");light.Save(Path.Combine(output,"spotlight-offscreen.png"));}var dots=ScreenCraftTests.Mark(Tool.Pixelate,120,80,220,140);dots.RedactionMode=2;c.AddAnnotation(dots);using(var result=c.Render())check(result.GetPixel(120,80).ToArgb()!=c.Img.GetPixel(120,80).ToArgb(),"spotlight restored redacted source");}});
            run("watermark/repeated rotated text is editable undoable and roundtrips with all effect flags",delegate{using(var c=new Canvas(Source(500,330))){var watermark=WatermarkDialog.Create(c.Crop,"STUDIO / 分析",22,25,-25,70,Color.DarkSlateBlue);c.AddAnnotation(watermark);using(var marked=c.Render()){check(Different(marked,c.Img,new Rectangle(0,0,500,330))>100,"watermark not drawn");marked.Save(Path.Combine(output,"text-watermark-offscreen.png"));using(var doc=c.ExportDocument()){var path=Path.Combine(output,"effects-watermark.sccraft");doc.Save(path);using(var opened=AnnotationDocument.Open(path))using(var reread=opened.Render())check(Hash(marked)==Hash(reread)&&opened.Shapes[0].WatermarkAngle== -25,"watermark not preserved");}}c.Undo();check(c.AnnotationCount==0,"watermark undo");}});
            run("extras/actual secondary buttons apply smooth freehand arrow white edge and blur modes",delegate{using(var o=Overlay()){var c=o.AnnotationCanvas;var buttons=Children(o).OfType<Button>().ToArray();c.SetTool(Tool.Pen);Click(buttons.Single(b=>b.AccessibleName=="平滑画笔线条"));Click(buttons.Single(b=>b.AccessibleName=="自由曲线箭头"));check(c.DefaultStyle.SmoothPen&&c.DefaultStyle.FreehandArrow,"pen controls disconnected");c.SetTool(Tool.Arrow);Click(buttons.Single(b=>b.AccessibleName=="白边醒目箭头"));check(c.DefaultStyle.ArrowWhiteOutline&&!c.DefaultStyle.SimpleArrow&&c.DefaultStyle.Width>=6,"white edge control disconnected");c.SetTool(Tool.Pixelate);Click(buttons.Single(b=>b.AccessibleName=="柔化模糊"));check(c.DefaultStyle.RedactionMode==1,"blur control");Click(buttons.Single(b=>b.AccessibleName=="彩点遮盖"));check(c.DefaultStyle.RedactionMode==2,"dots control");}});
            run("extras/paint modes and guide opt-out persist without changing legacy defaults",delegate{var store=new PreferenceStore(Path.Combine(output,"extras-preferences"));Directory.CreateDirectory(store.DirectoryPath);File.WriteAllText(store.FilePath,"{\"Version\":1}");check(store.Load().ShowCaptureGuides,"missing guide setting not defaulted");var p=store.Load();p.ShowCaptureGuides=false;store.Save(p);check(!store.Load().ShowCaptureGuides,"guide opt-out lost");using(var c=new Canvas(Source(400,260))){var pen=ScreenCraftTests.Mark(Tool.Pen,20,20,180,100);pen.Points=new List<PointF>{pen.A,new PointF(70,80),pen.B};pen.SmoothPen=true;pen.FreehandArrow=true;c.AddAnnotation(pen);var arrow=ScreenCraftTests.Mark(Tool.Arrow,40,170,300,190);arrow.ArrowWhiteOutline=true;c.AddAnnotation(arrow);var mark=ScreenCraftTests.Mark(Tool.Pixelate,200,40,300,90);mark.RedactionMode=2;c.AddAnnotation(mark);using(var doc=c.ExportDocument()){string path=Path.Combine(output,"stroke-effects.sccraft");doc.Save(path);using(var read=AnnotationDocument.Open(path))check(read.Shapes[0].SmoothPen&&read.Shapes[0].FreehandArrow&&read.Shapes[1].ArrowWhiteOutline&&read.Shapes[2].RedactionMode==2,"new effect flags lost");}}});
            run("pen/Shift production gesture constrains freehand to horizontal or vertical segments",delegate{using(var owner=new Form{ClientSize=new Size(800,520)})using(var c=new ShiftPen(Source(400,260))){owner.Controls.Add(c);c.Bounds=owner.ClientRectangle;c.SetTool(Tool.Pen);c.Stroke(new PointF(30,60),new PointF(90,64),new PointF(180,68));check(c.AnnotationCount==1&&c.AnnotationSnapshot[0].Points.Count==2&&c.AnnotationSnapshot[0].Points.All(p=>Math.Abs(p.Y-60)<1),"horizontal constraint failed");c.SetTool(Tool.Pen);c.Stroke(new PointF(260,30),new PointF(264,80),new PointF(268,180));check(c.AnnotationCount==2&&c.AnnotationSnapshot[1].Points.Count==2&&c.AnnotationSnapshot[1].Points.All(p=>Math.Abs(p.X-260)<1),"vertical constraint failed");check(!owner.Visible,"gesture showed UI");}});
            run("capture/copy and continue uses production menu action preserves editor and reports failed clipboard",delegate{using(var o=Overlay()){int copies=0;o.CopyOutput=delegate(Bitmap image){copies++;check(image.Width==750&&image.Height==430,"copy dimensions");};var menu=o.PrepareMoreMenu();menu.Items.OfType<CraftMenuItem>().Single(i=>i.Text.StartsWith("复制并继续")).PerformClick();check(copies==1&&!o.IsDisposed&&!menu.IsDisposed,"copy closed capture or disposed popup");Click(Children(o).OfType<Button>().Single(b=>b.AccessibleName=="聚光灯 F"));check(o.AnnotationCanvas.Tool==Tool.Spotlight,"spotlight menu disconnected");string error=null;o.CopyOutput=delegate{throw new System.Runtime.InteropServices.ExternalException("fixture clipboard busy");};o.CommandError=delegate(string message){error=message;};menu.Items.OfType<CraftMenuItem>().Single(i=>i.Text.StartsWith("复制并继续")).PerformClick();check(error!=null&&error.Contains("fixture clipboard busy")&&!o.IsDisposed,"failed copy lost editor");}});
        }
    }
}
